def slugify(s):
    s = s.lower()
    transliteration = {
        'õ': 'o',
        'ä': 'a',
        'ö': 'o',
        'ü': 'u',
        'š': 's',
        'ž': 'z',
    }
    out = []
    for ch in s:
        if ch in transliteration:
            out.append(transliteration[ch])
        elif ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive dashes
    result = ''
    prev_dash = False
    for ch in out:
        if ch == '-':
            if not prev_dash:
                result += '-'
            prev_dash = True
        else:
            result += ch
            prev_dash = False
    return result.strip('-')

import unicodedata

def slugify(s):
    s = s.lower()
    # Transliterate: decompose and strip combining marks
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    prev_dash = True
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_dash = False
        else:
            if not prev_dash:
                out.append('-')
            prev_dash = True
    return ''.join(out)

import unicodedata

def slugify(s):
    s = s.lower()
    # Transliterate: decompose and drop combining marks (e.g. õ -> o)
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    return ''.join(out).rstrip('-')

